body { font-family: 'Inter', system-ui, sans-serif; background: var(--steel); color: var(--navy); margin: 0; }
.nav { display: flex; justify-content: space-between; padding: 2rem; border-bottom: 2px solid #E2E8F0; }
.hero { padding: 4rem 2rem; text-align: center; }
.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 2rem; padding: 2rem; }
.card { background: white; padding: 2rem; border: 1px solid #E2E8F0; border-radius: 8px; }
button { background: var(--blue); color: white; padding: 0.75rem 1.5rem; border: none; border-radius: 4px; cursor: pointer; }

