import { createServer } from 'http';

const server = createServer((req, res) => {
  res.setHeader('Content-Type', 'application/json');
  if (req.method === 'POST') {
    res.end(JSON.stringify({ status: 'success', message: 'Inquiry received' }));
  } else {
    res.end(JSON.stringify({ name: 'King Ken Nation', engineer: 'Akinwumi Kehinde' }));
  }
});
server.listen(3000);
